input[type=text], select {
  font: inherit; color: var(--ink); background: #170b24;
  border: 1px solid var(--line); border-radius: 6px; padding: 8px 10px; width: 100%;
}
input[type=text]:focus, select:focus { outline: 2px solid var(--gold); outline-offset: 1px; }
input[type=range] { width: 100%; accent-color: var(--gold); }

/* --- Layout --- */
.studio {
  display: grid; grid-template-columns: 268px minmax(0, 1fr) 268px; gap: 16px;
  padding: 16px 20px; align-items: start;
}
.rail { display: flex; flex-direction: column; gap: 14px; }
.card {
  background: var(--card); border: 1px solid var(--line); border-radius: 12px;
  padding: 14px; display: flex; flex-direction: column; gap: 10px;
}
.card h2 {
  margin: 0; font-family: 'Anton', 'Arial Narrow', sans-serif;
  font-size: 15px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--gold);
}
.hint { margin: 0; font-size: 12px; color: var(--muted); }

/* --- Photo tray --- */
.tray { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.tray-thumb {
  position: relative; padding: 0; border: 2px solid var(--line); border-radius: 8px;
  overflow: hidden; cursor: pointer; background: #170b24; color: var(--ink);
  font: inherit; text-align: left;
}
.tray-thumb img { display: block; width: 100%; height: 74px; object-fit: cover; }
.tray-thumb span {
  display: block; padding: 4px 6px; font-size: 12px; font-weight: 700;
  background: rgba(20, 8, 31, 0.85);
}
.tray-thumb.assigned { border-color: var(--gold); box-shadow: 0 0 0 2px var(--gold); }
.upload {
  display: block; text-align: center; padding: 10px; border: 2px dashed var(--line);
  border-radius: 8px; cursor: pointer; color: var(--gold); font-weight: 700;
}
.upload input { display: none; }
.upload:hover { border-color: var(--gold); }

/* --- Panel nav --- */
.panel-nav { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.panel-nav span { font-weight: 700; }

/* --- Stage / preview --- */
.stage { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.aspect-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.aspect-label { font-weight: 700; color: var(--muted); font-size: 13px; }
.preview-wrap {
  background: #0d0616; border: 1px solid var(--line); border-radius: 12px;
  padding: 12px; display: grid; place-items: center;
}
#preview {
  max-width: 100%; max-height: 62vh; width: auto; height: auto;
  border-radius: 4px; box-shadow: 0 12px 40px rgba(0, 0, 0, 0.55);
  cursor: crosshair; touch-action: none;
}
.status { margin: 0; color: var(--gold); font-size: 13px; min-height: 18px; }

/* --- Right rail bits --- */
.layout-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.checks { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 10px; }
.checks label { flex-direction: row; align-items: center; gap: 7px; font-weight: 500; color: var(--ink); }
.checks input { accent-color: var(--gold); width: 16px; height: 16px; }
.export-card .btn { width: 100%; }

.foot {
  display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  padding: 10px 20px 16px; color: var(--muted); font-size: 12px;
}

/* --- Screenshot mode: cover alone, full viewport --- */
body.shot-cover .topbar,
body.shot-cover .rail,
body.shot-cover .foot,
body.shot-cover .aspect-row,
body.shot-cover .status { display: none; }
body.shot-cover .studio { display: block; padding: 0; }
body.shot-cover .stage { display: block; }
body.shot-cover .preview-wrap { padding: 0; border: 0; border-radius: 0; background: none; }
body.shot-cover #preview {
  display: block; width: 100vw; height: 100vh; max-height: none;
  border-radius: 0; box-shadow: none;
}

@media (max-width: 1100px) {
  .studio { grid-template-columns: 1fr; }
}
